import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

import {
  addNotice,
  getNotices,
  addStudy,
  uploadPDF
} from "../../services/api";

const AdminDashboard = () => {
  const navigate = useNavigate();

  // 🧠 STATES
  const [noticeTitle, setNoticeTitle] = useState("");
  const [noticeContent, setNoticeContent] = useState("");
  const [notices, setNotices] = useState([]);

  const [studyTitle, setStudyTitle] = useState("");
  const [studySubject, setStudySubject] = useState("");
  const [studyContent, setStudyContent] = useState("");

  const [file, setFile] = useState(null);

  // 🚀 LOAD NOTICES
  useEffect(() => {
    fetchNotices();
  }, []);

  const fetchNotices = async () => {
    try {
      const res = await getNotices();
      setNotices(res.data);
    } catch (err) {
      console.error("Error fetching notices:", err);
    }
  };

  // ➕ ADD NOTICE
  const handleAddNotice = async () => {
    try {
      await addNotice(
        { title: noticeTitle, content: noticeContent },
        "token"
      );

      setNoticeTitle("");
      setNoticeContent("");

      fetchNotices(); // refresh list
    } catch (err) {
      console.error("Add Notice Error:", err);
    }
  };

  // ➕ ADD STUDY
  const handleAddStudy = async () => {
    try {
      await addStudy(
        {
          title: studyTitle,
          subject: studySubject,
          content: studyContent
        },
        "token"
      );

      setStudyTitle("");
      setStudySubject("");
      setStudyContent("");
    } catch (err) {
      console.error("Add Study Error:", err);
    }
  };

  // 📁 UPLOAD PDF
  const handleUpload = async () => {
    try {
      await uploadPDF(file, "token");
      alert("PDF Uploaded!");
    } catch (err) {
      console.error("Upload Error:", err);
    }
  };

  return (
    <div style={styles.container}>

      {/* 🟢 SIDEBAR */}
      <div style={styles.sidebar}>
        <h2 style={styles.logo}>EduSaarthi</h2>

        <button style={styles.sideBtn} onClick={() => navigate("/admin")}>
          🏠 Dashboard
        </button>

        <button style={styles.sideBtn} onClick={() => navigate("/chatbot")}>
          🤖 Chatbot
        </button>
      </div>

      {/* 🟢 MAIN */}
      <div style={styles.main}>
        <h1>Admin Dashboard</h1>

        {/* 📢 NOTICES */}
        <div style={styles.card}>
          <h2>Notices</h2>

          <input
            placeholder="Title"
            value={noticeTitle}
            onChange={(e) => setNoticeTitle(e.target.value)}
            style={styles.input}
          />

          <input
            placeholder="Content"
            value={noticeContent}
            onChange={(e) => setNoticeContent(e.target.value)}
            style={styles.input}
          />

          <button style={styles.button} onClick={handleAddNotice}>
            Add Notice
          </button>

          {/* 🔥 SHOW NOTICES */}
          <h3 style={{ marginTop: "20px" }}>All Notices</h3>

          {notices.map((n, i) => (
            <div key={i} style={styles.noticeBox}>
              <b>{n.title}</b>
              <p>{n.content}</p>
            </div>
          ))}
        </div>

        {/* 📚 STUDY */}
        <div style={styles.card}>
          <h2>Study Material</h2>

          <input
            placeholder="Title"
            value={studyTitle}
            onChange={(e) => setStudyTitle(e.target.value)}
            style={styles.input}
          />

          <input
            placeholder="Subject"
            value={studySubject}
            onChange={(e) => setStudySubject(e.target.value)}
            style={styles.input}
          />

          <input
            placeholder="Content"
            value={studyContent}
            onChange={(e) => setStudyContent(e.target.value)}
            style={styles.input}
          />

          <button style={styles.button} onClick={handleAddStudy}>
            Add Study
          </button>
        </div>

        {/* 📁 UPLOAD */}
        <div style={styles.card}>
          <h2>Upload PDF</h2>

          <input
            type="file"
            onChange={(e) => setFile(e.target.files[0])}
          />

          <button style={styles.button} onClick={handleUpload}>
            Upload PDF
          </button>
        </div>

      </div>
    </div>
  );
};

export default AdminDashboard;


// 🎨 STYLES
const styles = {
  container: {
    display: "flex",
    height: "100vh",
    background: "#0f172a",
    color: "white",
  },
  sidebar: {
    width: "200px",
    background: "#111827",
    padding: "20px",
  },
  logo: {
    marginBottom: "20px",
    color: "#38bdf8",
  },
  sideBtn: {
    display: "block",
    width: "100%",
    marginBottom: "10px",
    padding: "10px",
    background: "#1f2937",
    color: "white",
    border: "none",
    cursor: "pointer",
  },
  main: {
    flex: 1,
    padding: "20px",
    overflowY: "auto",
  },
  card: {
    background: "#1e293b",
    padding: "20px",
    borderRadius: "10px",
    marginBottom: "20px",
  },
  input: {
    width: "100%",
    padding: "10px",
    margin: "5px 0",
  },
  button: {
    marginTop: "10px",
    padding: "10px",
    background: "#38bdf8",
    border: "none",
    cursor: "pointer",
  },
  noticeBox: {
    background: "#334155",
    padding: "10px",
    marginTop: "10px",
    borderRadius: "5px",
  }
};
